/*
 * Sample catalogue. Single source for both the in-browser sample backend and
 * supabase/seed.sql (generated by scripts/generate-seed.ts, checked by
 * tests/unit/seed.test.ts). Keep this file free of runtime imports so Node can
 * load it directly.
 */
import type { Category, OrderStatus, ProductImage, Role } from '../../../types/index.ts'

type ProductRow = {
  id: string
  created_at: string
  category_id: string
  name: string
  slug: string
  description: string
  price_cents: number
  stock: number
  is_active: boolean
}

/**
 * Stable ids so the seed can be re-run safely. The first block is mixed so
 * short order numbers (its first eight characters) look different per record.
 */
function uuid(group: number, n: number): string {
  const head = (Math.imul(group * 131 + n, 0x9e3779b1) >>> 0).toString(16).padStart(8, '0')
  return `${head}-0000-4000-8000-${String(group).padStart(4, '0')}${String(n).padStart(8, '0')}`
}

function at(minutes: number): string {
  return new Date(Date.UTC(2026, 0, 5, 9, minutes)).toISOString()
}

