function categoryId(slug: Seed['category']): string {
  const category = SAMPLE_CATEGORIES.find((entry) => entry.slug === slug)
  if (!category) throw new Error(`Unknown sample category: ${slug}`)
  return category.id
}

export const SAMPLE_PRODUCTS: ProductRow[] = SEEDS.map((seed, index) => ({
  id: uuid(2, index + 1),
  created_at: at(index + 1),
  category_id: categoryId(seed.category),
  name: seed.name,
  slug: seed.slug,
  description: seed.description,
  price_cents: seed.price_cents,
  stock: seed.stock,
  is_active: seed.is_active ?? true,
}))

export const SAMPLE_PRODUCT_IMAGES: ProductImage[] = SEEDS.map((seed, index) => ({
  id: uuid(3, index + 1),
  created_at: at(index + 1),
  product_id: uuid(2, index + 1),
  storage_path: seed.illustration,
  alt_text: seed.alt_text,
  sort_order: 0,
}))

